public int minInsertions(String s) {
    int open = 0; // Count of unmatched '('
    int close = 0; // Count of unmatched ')'
    int insertions = 0; // Total insertions required

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (close % 2 != 0) {
                insertions++; // Add a ')'
                close--;
            }
            open++;
        } else {
            close++;
            if (close > open * 2) {
                insertions++; // Add a '('
                open++;
            }
        }
    }

    return insertions + open * 2 - close; // Total insertions
}

