    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
        }
    }

    // If there are fewer than k factors, return -1
    if (factors.size() < k) {
        return -1;
    }

    // Return the k-th factor (0-based index)
    return factors.get(k - 1);
}

