        for (int i = 0; i < length; i++) {
            int digit = str.charAt(i) - '0';
            int higher = str.substring(0, i).isEmpty() ? 0 : Integer.parseInt(str.substring(0, i));
            int lower = str.substring(i + 1).isEmpty() ? 0 : Integer.parseInt(str.substring(i + 1));

            if (digit == 0) {
                count += higher * Math.pow(10, length - i - 1);
