        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 0) {
                continue;
            }

            int[] directions = {0, 1, 1, 1}; // Horizontal, Vertical, Diagonal, Anti-diagonal
            int[] increments = {0, 1, -1, 1}; // Corresponding increments for row and col

            for (int d = 0; d < 4; d++) {
                int dirRow = i + increments[d];
                int dirCol = j + increments[d + 1];
                int length = 1;

                while (dirRow >= 0 && dirRow < rows && dirCol >= 0 && dirCol < cols && mat[dirRow][dirCol] == 1) {
                    length++;
                    dirRow += increments[d];
                    dirCol += increments[d + 1];
                }

