public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i <= heights.length; i++) {
        while (!stack.isEmpty() && (i == heights.length || heights[stack.peek()] >= heights[i])) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, index = 0;

    while (r < rows && c < cols) {
        result[index++] = mat[r][c];
        if ((r + c) % 2 == 0) { // Move up and to the right
            if (c == cols - 1) {
                r++;
            } else if (r == 0) {
                c++;
            } else {
                r--;
                c++;
            }
        } else { // Move down and to the left
            if (r == rows - 1) {
                c++;
            } else if (c == 0) {
                r++;
            } else {
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
        char[] digits = Integer.toString(n).toCharArray();

        // Convert char array to priority queue to sort digits
        PriorityQueue<Character> minHeap = new PriorityQueue<>();
        for (char digit : digits) {
            minHeap.add(digit);
        }

        // Start from the second last digit and try to find a digit that is smaller than the next digit
        for (int i = digits.length - 2; i >= 0; i--) {
            if (digits[i] < digits[i + 1]) {
                // Remove the next digit from the heap
                char nextDigit = minHeap.poll();

                // Find the smallest digit in the heap that is greater than the current digit
                while (!minHeap.isEmpty() && minHeap.peek() <= digits[i]) {
                    minHeap.poll();
                }

                // Swap the found digit with the current digit
                char temp = digits[i];
                digits[i] = minHeap.poll();
                digits[i + 1] = temp;

                // Sort the remaining digits to get the smallest arrangement
                Arrays.sort(digits, i + 2, digits.length);

                // Convert the char array back to integer
                return Integer.parseInt(new String(digits));
            }
        }

        // If no such digit is found, return -1
        return -1;
    }

public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n == 1) {
            result.add("0");
            result.add("1");
            result.add("8");
            return result;
        }

        if (n == 2) {
            result.add("11");
            result.add("69");
            result.add("88");
            result.add("96");
            return result;
        }

        char[] options = {'1', '6', '8', '9'};
        char[] midOptions = {'0', '1', '8'};

        generate(result, new char[n], 0, n - 1, options, midOptions);

        return result;
    }

private static void generate(List<String> result, char[] current, int left, int right, char[] options, char[] midOptions) {
        if (left > right) {
            result.add(new String(current));
            return;
        }

        if (left == right) {
            for (char mid : midOptions) {
                current[left] = mid;
                result.add(new String(current));
            }
            return;
        }

        for (char option : options) {
            if (left == 0 && option == '0') continue;
            current[left] = option;
            current[right] = getSymmetric(option);
            generate(result, current, left + 1, right - 1, options, midOptions);
        }
    }

private static char getSymmetric(char c) {
        if (c == '6') return '9';
        if (c == '9') return '6';
        return c;
    }

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        throw new IllegalArgumentException("Input must be an array of 3 points.");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if the area of the triangle formed by the points is zero
    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;
    int nextUglyNumber = 1;

    for (int i = 1; i < n; i++) {
        nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            i2++;
            nextMultipleOf2 = uglyNumbers[i2] * 2;
        }
        if (nextUglyNumber == nextMultipleOf3) {
            i3++;
            nextMultipleOf3 = uglyNumbers[i3] * 3;
        }
        if (nextUglyNumber == nextMultipleOf5) {
            i5++;
            nextMultipleOf5 = uglyNumbers[i5] * 5;
        }
    }

    return nextUglyNumber;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 0;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy);
    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort(Comparator.comparingInt(String::valueOf));
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Map<Integer, Integer> elementCounts = new HashMap<>();
    for (int num : nums) {
        elementCounts.put(num, elementCounts.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : elementCounts.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 3) {
        return n;
    }

    int[] dp = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = i;
    }

    for (int i = 4; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word).reverse();
        result.append(reversedWord).append(" ");
    }

    if (result.length() > 0) {
        result.setLength(result.length() - 1);
    }

    return result.toString();
}
